diff --git a/src/log.ts b/src/log.ts
index 4892c8b..5846d7a 100644
--- a/src/log.ts
+++ b/src/log.ts
@@ -1,3 +1,23 @@
+let queue: string[] = [];
+let flushing = false;
+
+const flush = (): void => {
+  if (flushing || queue.length === 0) return;
+  flushing = true;
+
+  const batch = queue;
+  queue = [];
+
+  const content = batch.join("");
+  process.stdout.write(content, () => {
+    flushing = false;
+    if (queue.length > 0) {
+      setImmediate(flush);
+    }
+  });
+};
+
 export const log = (message: string): void => {
-  process.stdout.write(`${JSON.stringify({ message })}\n`);
+  queue.push(`${JSON.stringify({ message })}\n`);
+  setImmediate(flush);
 };
